param([string]$SnapshotPath="data\research\v58\snapshots.csv",[double]$LongFraction=.20,[double]$TransactionCostBps=5,[int]$MinimumCycles=10,[int]$MinimumDays=5,[ValidateSet("real","external_unverified","synthetic","demo","test")][string]$Provenance="external_unverified")
$ErrorActionPreference="Stop";Set-Location(Resolve-Path(Join-Path $PSScriptRoot ".."));$env:FINAI_V58_SNAPSHOT_PATH=$SnapshotPath;$env:FINAI_V58_LONG_FRACTION=$LongFraction.ToString([Globalization.CultureInfo]::InvariantCulture);$env:FINAI_V58_COST_BPS=$TransactionCostBps.ToString([Globalization.CultureInfo]::InvariantCulture);$env:FINAI_V58_MIN_CYCLES="$MinimumCycles";$env:FINAI_V58_MIN_DAYS="$MinimumDays";$env:FINAI_V58_PROVENANCE=$Provenance
